"""Generated by the NL to Flow Diagram Encoder Pipeline."""

def hasCycle(head):
    slow = head
    fast = head
    while ((fast is not None) and (fast.next is not None)):
        slow = slow.next
        fast = fast.next.next
        if (slow == fast):
            return True
    return False

class Node:
    def __init__(self, value):
        self.value = value
        self.next = None


# Build a list with a cycle:
# 1 → 2 → 3 → 4
#       ↑     ↓
#       ← ← ← ←

A = Node(1)
B = Node(2)
C = Node(3)
D = Node(4)

A.next = B
B.next = C
C.next = D
D.next = B   # cycle here

print(hasCycle(A))   # True


# Build a list without a cycle:
X = Node(10)
Y = Node(20)
Z = Node(30)

X.next = Y
Y.next = Z

print(hasCycle(X))   # False
